values(8,'listening','IELTS Listening Test 198','published',$json${"version":"listening-test-198-v1","test_code":"TEST-198","audio_url":"https://ia601904.us.archive.org/4/items/test-198-ready/TEST_198_ready.mp3","total_questions":40,"audio_once":true,"sections":[{"number":1,"label":"SECTION 1","range":"Questions 1–10","blocks":[{"kind":"notes","range":"Questions 1–5","instruction":"Complete the notes below.","word_limit":"Write ONE WORD ONLY for each answer.","title":"Poppy Reserve in Sandcastle","items":[["Almond Valley Poppy Reserve is a nature reserve."],["The poppies will be at their best at the end of the ",{"q":1},"."],["The poppies on the hills are ",{"q":2}," in colour."],["The reserve is located to the ",{"q":3}," of Lakeside."],["The best time for photography is mid-afternoon."],["Wear ",{"q":4}," because of rattlesnakes."],["The reserve is a ",{"q":5}," park."]]},{"kind":"table","range":"Questions 6–10","instruction":"Complete the table below.","word_limit":"Write ONE WORD AND/OR A NUMBER for each answer.","title":"Poppy Reserve Tours","headers":["Tour","Start time","Duration","Highlights","Photography"],"rows":[[["The ",{"q":6}," tour"],["every hour from 7:30 a.m."],["30 minutes"],["viewpoints, film and the ",{"q":7}],["panoramic pictures"]],[["The Wildflower tour"],["every two hours from 8:00 a.m."],[{"q":8}],["poppy, cream cup, and sage"],["close-up tips"]],[["The Wildlife tour"],[{"q":9}," a.m. or 7:00 p.m."],["1.5 hours"],["coyote, quail, roadrunners"],["bring tripod and a ",{"q":10}," lens"]]]}]},{"number":2,"label":"SECTION 2","range":"Questions 11–20","blocks":[{"kind":"mcq","range":"Questions 11–15","instruction":"Choose the correct letter, A, B or C.","title":"Re-creating life in an Iron Age village","questions":[{"q":11,"text":"Jim says that in the Iron Age village","options":{"A":"he is sometimes cold at night.","B":"he always gets up early.","C":"he has time to himself."}},{"q":12,"text":"What does Jim say about the food they eat in the village?","options":{"A":"It takes time to prepare.","B":"It is difficult to get used to.","C":"It has to be eaten quickly."}},{"q":13,"text":"Jim says that at the evening meal","options":{"A":"they are sometimes too tired to eat.","B":"they mainly have fruit and berries.","C":"they talk about what they’ve done."}},{"q":14,"text":"The most important job for the blacksmiths is","options":{"A":"to mend broken tools and implements.","B":"to maintain a good source of heat.","C":"to collect sufficient firewood."}},{"q":15,"text":"Jim likes the fact that in the village, people","options":{"A":"do varied activities.","B":"share their knowledge.","C":"get a lot of exercise."}}]},{"kind":"matching","range":"Questions 16–20","instruction":"Complete the flow-chart below. Choose FIVE answers from the box and write the correct letter.","word_limit":"Choose from A–I.","title":"MAKING AN IRON AGE ROUNDHOUSE","choices":{"A":"bone","B":"different","C":"equal","D":"elm","E":"hazel","F":"iron","G":"peg","H":"roof","I":"scaffold"},"items":[{"q":16,"text":"Mark centre of planned house with a ..."},{"q":17,"text":"Mark out circle for outer boundary → Dig ground using tools made from ..."},{"q":18,"text":"Insert wall posts (oak preferred), slot stakes into upright posts → Insert centre post and build a wooden ... around it."},{"q":19,"text":"Add main supporting beams and ring beams → Complete roof framework using ... wood rods."},{"q":20,"text":"Cover roof with reed bundles of ... lengths → Daub with clay, dung and straw."}]}]},{"number":3,"label":"SECTION 3","range":"Questions 21–30","blocks":[{"kind":"mcq","range":"Questions 21–26","instruction":"Choose the correct letter, A, B or C.","title":"Organising a debate","questions":[{"q":21,"text":"Why is Fiona keen to organise a debate?","options":{"A":"She has attended debates in other departments.","B":"She organised debates while at secondary school.","C":"She has talked about debating with a friend."}},{"q":22,"text":"Fiona says that an advantage of debating is that it can","options":{"A":"help students to form opinions.","B":"improve students’ listening skills.","C":"develop students’ self-confidence."}},{"q":23,"text":"How will the debate topic be selected?","options":{"A":"Daniel and Fiona will ask the lecturer to choose one from a list.","B":"The other students will select one of Daniel and Fiona’s suggestions.","C":"Daniel and Fiona will collect suggestions from the other students."}},{"q":24,"text":"Daniel and Fiona think one key to a successful debate is for students to","options":{"A":"have a topic that really involves them.","B":"plan their speech carefully.","C":"be given positions to defend."}},{"q":25,"text":"Daniel thinks it would be good for the students to be in two teams because it would","options":{"A":"give everyone a chance to speak.","B":"help students with less confidence.","C":"share out the preparation required."}},{"q":26,"text":"What does the lecturer agree to do after the debate?","options":{"A":"make comments on students’ written work.","B":"help Daniel and Fiona to write a report.","C":"set the students an essay on a different topic."}}]},{"kind":"matching","range":"Questions 27–30","instruction":"What will Daniel and Fiona do at the meeting to help students with debate? Choose FOUR answers from the box.","word_limit":"Choose from A–F.","title":"Actions at the meeting — Aspects of a debate","choices":{"A":"ask for suggestions","B":"give a handout of key points","C":"write on the board","D":"provide a photocopy of an article","E":"recommend a textbook","F":"give a demonstration"},"items":[{"q":27,"text":"Understanding debating procedures"},{"q":28,"text":"Using body language"},{"q":29,"text":"Accessing resources"},{"q":30,"text":"Asking and answering questions"}]}]},{"number":4,"label":"SECTION 4","range":"Questions 31–40","blocks":[{"kind":"notes_groups","range":"Questions 31–40","instruction":"Complete the notes below.","word_limit":"Write ONE WORD ONLY for each answer.","title":"Office Design","groups":[{"heading":"Early 20th Century","items":[["workers employed to do ",{"q":31}," were arranged in rows"]]},{"heading":"1960s to present","intro":"Variations in design of open-plan offices:","items":[["first, workers had individual ",{"q":32}],["later, they had cubicles with high or low ",{"q":33}],["nowadays, workers may have to ",{"q":34}," a work area"]]},{"heading":"Survey results — attitudes of employees to open-plan designs","items":[["there is a lack of ",{"q":35}," and ",{"q":36}],["they pose a risk to our ",{"q":37}," (staff records support this)"]]},{"heading":"Survey results — attitudes of employers to open-plan designs","items":[["they significantly reduce rent and ",{"q":38}," costs"],["they improve teamwork and communication"],["they can make ",{"q":39}," staff easier"]]},{"heading":"In reality","items":[["employees are unhappy and they are often distracted by the ",{"q":40}," in the office."]]}]}]}],"answer_key":{"1":["month"],"2":["orange"],"3":["east"],"4":["trousers"],"5":["state"],"6":["general"],"7":["museum"],"8":["1 hour","1 hr","60 minutes","60 mins"],"9":["5:30","5.30","05:30","05.30"],"10":["zoom"],"11":["B"],"12":["A"],"13":["C"],"14":["B"],"15":["A"],"16":["G"],"17":["A"],"18":["I"],"19":["E"],"20":["C"],"21":["C"],"22":["A"],"23":["B"],"24":["A"],"25":["C"],"26":["A"],"27":["B"],"28":["D"],"29":["A"],"30":["C"],"31":["typing"],"32":["desks"],"33":["screens"],"34":["share"],"35":["privacy"],"36":["security"],"37":["health"],"38":["energy"],"39":["training"],"40":["noise"]}}$json$::jsonb,now(),now())
